package main

import (
	"os"
	"path/filepath"
	"testing"
)

// TestOverwriteAllowedRequiresHeader pins that the -out overwrite guard
// judges a file by its generated-file HEADER (a marker comment before the
// package clause), not by the marker text appearing anywhere: a
// hand-written file that merely mentions "Code generated by zerojsongen"
// in a later comment must be protected.
func TestOverwriteAllowedRequiresHeader(t *testing.T) {
	dir := t.TempDir()
	write := func(name, src string) string {
		p := filepath.Join(dir, name)
		if err := os.WriteFile(p, []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
		return p
	}
	cases := []struct {
		name  string
		src   string
		allow bool
	}{
		{"absent", "", true},
		{"zerojsongen header", "// Code generated by zerojsongen. DO NOT EDIT.\n\npackage p\n", true},
		{"easyjson header", "// Code generated by easyjson for marshaling/unmarshaling. DO NOT EDIT.\n\npackage p\n", true},
		{"hand-written mentioning the marker later", "package p\n\n// This file is NOT \"Code generated by zerojsongen. DO NOT EDIT.\" — hand-written.\nconst Keep = 1\n", false},
		{"hand-written mentioning the marker in the package doc", "// Package p is hand-written; do not confuse with Code generated by zerojsongen. DO NOT EDIT. output.\npackage p\n", false},
		{"other generator header", "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage p\n", false},
		{"does not parse", "this is not go\n", false},
	}
	for _, c := range cases {
		p := filepath.Join(dir, "absent.go")
		if c.src != "" {
			p = write(c.name+".go", c.src)
		}
		if got := overwriteAllowed(p); got != c.allow {
			t.Errorf("%s: overwriteAllowed=%v want %v", c.name, got, c.allow)
		}
	}
}
